/**
 * All test variants preserve question IDs and topics. We deliberately retain
 * at least one true answer and two plausible false alternatives per item.
 * Where a question has more true answers than fit into six choices, omit a
 * subset of true statements (never relabel them as false).
 */
export function improveQuestion(question: Question): Question {
  const originalCorrect = new Set(question.correctIds);
  const trueChoices = question.choices.filter((choice) => originalCorrect.has(choice.id));
  const falseChoices = question.choices.filter((choice) => !originalCorrect.has(choice.id));
  const added = (additionalIncorrectChoices[question.id] ?? []).map(
    ([hu, en], index): Choice => ({
      id: "v" + (index + 1),
      text: { hu, en }
    })
  );

  const selectedTrue = trueChoices.slice(0, 4);
  const availableFalse = [...falseChoices, ...added];
  const targetFalse = Math.max(2, Math.min(3, 6 - selectedTrue.length));
  const selectedFalse = availableFalse.slice(0, targetFalse);

  // Fail fast if a question cannot be repaired with independently authored facts.
  if (selectedTrue.length === 0 || selectedFalse.length < 2) {
    throw new Error("Incomplete bilingual quiz editorial review: " + question.id);
  }

  const chosen = shuffle([...selectedTrue, ...selectedFalse]).map((choice) => ({
    ...choice,
    text: { hu: polishHu(choice.text.hu), en: choice.text.en }
  }));
  const newCorrectIds = selectedTrue.map((choice) => choice.id);

  return {
    ...question,
    prompt: questionPrompts[question.id] ?? {
      ...question.prompt,
      hu: polishHu(question.prompt.hu)
    },
    explanation: explanationFixes[question.id] ?? {
      ...question.explanation,
      hu: polishHu(question.explanation.hu)
    },
    choices: chosen,
    correctIds: newCorrectIds
  };
}
